"""
LLM Integration Layer
Supports multiple local LLM backends with unified interface.
"""

from pathlib import Path
from typing import List, Dict, Optional, Iterator
from abc import ABC, abstractmethod
import json


class Message:
    """Represents a chat message."""

    def __init__(self, role: str, content: str):
        self.role = role  # 'system', 'user', or 'assistant'
        self.content = content

    def to_dict(self) -> dict:
        return {"role": self.role, "content": self.content}


class LLMBackend(ABC):
    """Abstract base class for LLM backends."""

    @abstractmethod
    def generate(self, messages: List[Message], temperature: float = 0.7,
                 max_tokens: int = 2000, stream: bool = False) -> str | Iterator[str]:
        """Generate a response from the LLM."""
        pass

    @abstractmethod
    def is_available(self) -> bool:
        """Check if this backend is available."""
        pass


class LlamaCppBackend(LLMBackend):
    """Backend for llama-cpp-python."""

    def __init__(self, model_path: Path, **kwargs):
        """
        Initialize llama.cpp backend.

        Args:
            model_path: Path to GGUF model file
            **kwargs: Additional arguments for Llama()
        """
        self.model_path = model_path
        self.model = None
        self.init_kwargs = kwargs
        self._initialize()

    def _initialize(self):
        """Load the model."""
        try:
            from llama_cpp import Llama

            default_kwargs = {
                'n_ctx': 4096,
                'n_threads': 4,
                'n_gpu_layers': 35,  # Adjust based on your GPU
            }
            default_kwargs.update(self.init_kwargs)

            self.model = Llama(
                model_path=str(self.model_path),
                **default_kwargs
            )
        except ImportError:
            raise ImportError("llama-cpp-python not installed. Run: pip install llama-cpp-python")
        except Exception as e:
            raise RuntimeError(f"Failed to load model: {e}")

    def generate(self, messages: List[Message], temperature: float = 0.7,
                 max_tokens: int = 2000, stream: bool = False) -> str | Iterator[str]:
        """Generate response using llama.cpp."""

        # Convert messages to llama.cpp format
        formatted_messages = [msg.to_dict() for msg in messages]

        response = self.model.create_chat_completion(
            messages=formatted_messages,
            temperature=temperature,
            max_tokens=max_tokens,
            stream=stream
        )

        if stream:
            def stream_generator():
                for chunk in response:
                    if 'choices' in chunk and len(chunk['choices']) > 0:
                        delta = chunk['choices'][0].get('delta', {})
                        content = delta.get('content', '')
                        if content:
                            yield content
            return stream_generator()
        else:
            return response['choices'][0]['message']['content']

    def is_available(self) -> bool:
        """Check if llama-cpp-python is available."""
        try:
            import llama_cpp
            return self.model_path.exists()
        except ImportError:
            return False


class GPT4AllBackend(LLMBackend):
    """Backend for GPT4All."""

    def __init__(self, model_name: str = "mistral-7b-instruct-v0.1.Q4_0.gguf", **kwargs):
        """
        Initialize GPT4All backend.

        Args:
            model_name: Name of model to load
            **kwargs: Additional arguments
        """
        self.model_name = model_name
        self.model = None
        self.init_kwargs = kwargs
        self._initialize()

    def _initialize(self):
        """Load the model."""
        try:
            from gpt4all import GPT4All
            self.model = GPT4All(self.model_name, **self.init_kwargs)
        except ImportError:
            raise ImportError("gpt4all not installed. Run: pip install gpt4all")
        except Exception as e:
            raise RuntimeError(f"Failed to load model: {e}")

    def generate(self, messages: List[Message], temperature: float = 0.7,
                 max_tokens: int = 2000, stream: bool = False) -> str | Iterator[str]:
        """Generate response using GPT4All."""

        # Format messages for GPT4All
        formatted_messages = [msg.to_dict() for msg in messages]

        if stream:
            def stream_generator():
                for token in self.model.generate(
                    formatted_messages,
                    temp=temperature,
                    max_tokens=max_tokens,
                    streaming=True
                ):
                    yield token
            return stream_generator()
        else:
            response = self.model.generate(
                formatted_messages,
                temp=temperature,
                max_tokens=max_tokens
            )
            return response

    def is_available(self) -> bool:
        """Check if GPT4All is available."""
        try:
            import gpt4all
            return True
        except ImportError:
            return False


class TransformersBackend(LLMBackend):
    """Backend for HuggingFace Transformers."""

    def __init__(self, model_name: str, device: str = "auto", **kwargs):
        """
        Initialize Transformers backend.

        Args:
            model_name: HuggingFace model identifier
            device: Device to use ('cpu', 'cuda', 'auto')
            **kwargs: Additional arguments for model loading
        """
        self.model_name = model_name
        self.device = device
        self.model = None
        self.tokenizer = None
        self.init_kwargs = kwargs
        self._initialize()

    def _initialize(self):
        """Load the model and tokenizer."""
        try:
            from transformers import AutoModelForCausalLM, AutoTokenizer
            import torch

            self.tokenizer = AutoTokenizer.from_pretrained(self.model_name)
            self.model = AutoModelForCausalLM.from_pretrained(
                self.model_name,
                device_map=self.device,
                torch_dtype=torch.float16 if self.device != "cpu" else torch.float32,
                **self.init_kwargs
            )
        except ImportError:
            raise ImportError("transformers not installed. Run: pip install transformers torch")
        except Exception as e:
            raise RuntimeError(f"Failed to load model: {e}")

    def generate(self, messages: List[Message], temperature: float = 0.7,
                 max_tokens: int = 2000, stream: bool = False) -> str | Iterator[str]:
        """Generate response using Transformers."""
        import torch

        # Format messages into a single prompt
        # This is a simple format - adjust based on your model's requirements
        prompt = self._format_messages(messages)

        inputs = self.tokenizer(prompt, return_tensors="pt").to(self.model.device)

        generation_kwargs = {
            "max_new_tokens": max_tokens,
            "temperature": temperature,
            "do_sample": temperature > 0,
            "pad_token_id": self.tokenizer.eos_token_id,
        }

        if stream:
            # Streaming implementation would require TextIteratorStreamer
            # For simplicity, falling back to non-streaming
            pass

        with torch.no_grad():
            outputs = self.model.generate(**inputs, **generation_kwargs)

        response = self.tokenizer.decode(outputs[0][inputs['input_ids'].shape[1]:], 
                                        skip_special_tokens=True)
        return response

    def _format_messages(self, messages: List[Message]) -> str:
        """Format messages into a prompt string."""
        formatted = []
        for msg in messages:
            if msg.role == "system":
                formatted.append(f"System: {msg.content}")
            elif msg.role == "user":
                formatted.append(f"User: {msg.content}")
            elif msg.role == "assistant":
                formatted.append(f"Assistant: {msg.content}")
        formatted.append("Assistant:")
        return "\n\n".join(formatted)

    def is_available(self) -> bool:
        """Check if Transformers is available."""
        try:
            import transformers
            import torch
            return True
        except ImportError:
            return False


class LLMManager:
    """Manages LLM backend initialization and selection."""

    def __init__(self, config: dict):
        """
        Initialize LLM manager.

        Args:
            config: Configuration dictionary with backend settings
        """
        self.config = config
        self.backend: Optional[LLMBackend] = None
        self._initialize_backend()

    def _initialize_backend(self):
        """Initialize the configured backend."""
        backend_type = self.config.get('backend', 'llamacpp')

        if backend_type == 'llamacpp':
            model_path = Path(self.config['model_path'])
            self.backend = LlamaCppBackend(
                model_path=model_path,
                **self.config.get('backend_kwargs', {})
            )

        elif backend_type == 'gpt4all':
            self.backend = GPT4AllBackend(
                model_name=self.config.get('model_name', 'mistral-7b-instruct-v0.1.Q4_0.gguf'),
                **self.config.get('backend_kwargs', {})
            )

        elif backend_type == 'transformers':
            self.backend = TransformersBackend(
                model_name=self.config['model_name'],
                device=self.config.get('device', 'auto'),
                **self.config.get('backend_kwargs', {})
            )

        else:
            raise ValueError(f"Unknown backend type: {backend_type}")

    def generate(self, messages: List[Message], **kwargs) -> str | Iterator[str]:
        """Generate response using configured backend."""
        if self.backend is None:
            raise RuntimeError("Backend not initialized")

        return self.backend.generate(messages, **kwargs)

    @classmethod
    def from_config_file(cls, config_path: Path) -> 'LLMManager':
        """Load configuration from file and create manager."""
        with open(config_path, 'r') as f:
            config = json.load(f)
        return cls(config)

