class LLMManager:
    """Manages LLM backend initialization and selection."""

    def __init__(self, config: dict):
        """
        Initialize LLM manager.

        Args:
            config: Configuration dictionary with backend settings
        """
        self.config = config
        self.backend: Optional[LLMBackend] = None
        self._initialize_backend()

    def _initialize_backend(self):
        """Initialize the configured backend."""
        backend_type = self.config.get('backend', 'llamacpp')

        if backend_type == 'llamacpp':
            model_path = Path(self.config['model_path'])
            self.backend = LlamaCppBackend(
                model_path=model_path,
                **self.config.get('backend_kwargs', {})
            )

        elif backend_type == 'gpt4all':
            self.backend = GPT4AllBackend(
                model_name=self.config.get('model_name', 'mistral-7b-instruct-v0.1.Q4_0.gguf'),
                **self.config.get('backend_kwargs', {})
            )

        elif backend_type == 'transformers':
            self.backend = TransformersBackend(
                model_name=self.config['model_name'],
                device=self.config.get('device', 'auto'),
                **self.config.get('backend_kwargs', {})
            )

        else:
            raise ValueError(f"Unknown backend type: {backend_type}")

    def generate(self, messages: List[Message], **kwargs) -> str | Iterator[str]:
        """Generate response using configured backend."""
        if self.backend is None:
            raise RuntimeError("Backend not initialized")

        return self.backend.generate(messages, **kwargs)

    @classmethod
    def from_config_file(cls, config_path: Path) -> 'LLMManager':
        """Load configuration from file and create manager."""
        with open(config_path, 'r') as f:
            config = json.load(f)
        return cls(config)

